sect1.example:
   Clonazione di un oggetto


<?php
class SubObject
{
    static $instances = 0;
    public $instance;

    public function __construct() {
        $this->instance = ++self::$instances;
    }

    public function __clone() {
        $this->instance = ++self::$instances;
    }
}

class MyCloneable
{
    public $object1;
    public $object2;

    function __clone()
    {
        // forza la copia di $this->object1, che altrimenti
        // punterebbe alla stessa istanza.
        $this->object1 = clone $this->object1;
    }
}

$obj = new MyCloneable();

$obj->object1 = new SubObject();
$obj->object2 = new SubObject();

$obj2 = clone $obj;


print "Oggetto originale:\n";
print_r($obj);

print "Oggetto clonato:\n";
print_r($obj2);

?> 


   &example.outputs;


Oggetto originale:
MyCloneable Object
(
    [object1] => SubObject Object
        (
            [instance] => 1
        )

    [object2] => SubObject Object
        (
            [instance] => 2
        )

)
Oggetto clonato:
MyCloneable Object
(
    [object1] => SubObject Object
        (
            [instance] => 3
        )

    [object2] => SubObject Object
        (
            [instance] => 2
        )

)

   Accesso a un membro di un oggetto appena clonato


<?php
$dateTime = new DateTime();
echo (clone $dateTime)->format('Y');
?>


   &example.outputs.similar;


2016

sect2.example:
    Clonazione di un oggetto con sovrascrittura delle proprietà


<?php
class Point {
    public function __construct(
        public readonly int $x,
        public readonly int $y,
    ) {}

    public function withX(int $x): static
    {
        return clone($this, ['x' => $x]);
    }
}

$p = new Point(1, 2);
$q = $p->withX(10);

echo $q->x, ' ', $q->y;
?>


    &example.outputs;


10 2
